//! A minimal fullstack Dioxus app for testing `languages.rust.dioxus`.

use dioxus::prelude::*;

// regenerated by dx from tailwind.css on every build
const TAILWIND_CSS: Asset = asset!("/assets/tailwind.css");

fn main() {
    dioxus::launch(App);
}

/// The root component, rendered on the server and hydrated on the client.
#[component]
fn App() -> Element {
    // the server waits for this before rendering, so the greeting is part of
    // the server-rendered html
    let greeting = use_server_future(greeting)?;

    let greeting = match &*greeting.read() {
        Some(Ok(greeting)) => greeting.clone(),
        Some(Err(error)) => format!("the server couldn't greet us: {error}"),
        None => "waiting for the server...".to_string(),
    };

    rsx! {
        document::Stylesheet { href: TAILWIND_CSS }

        main {
            h1 { class: "text-3xl font-bold underline", "hello from dioxus simple" }
            p { id: "greeting", "{greeting}" }
        }
    }
}

/// Greets the client from the server.
#[get("/api/greeting")]
async fn greeting() -> Result<String> {
    Ok("the server says hello".to_string())
}
